// el-openglo-one-theme.js — a Plasma one-shot update (⊕ONE-THEME, W35).
// plasmashell runs each script under the shell's contents/updates/ once, on
// start, and records its path in plasmashellrc [Updates] performed= (measured on
// Plasma 6.7.5, 2026-09-22). Before W35 every EL surface shipped as six per-variant
// packages; a user's containments name those ids. This moves them to the one ids,
// keeping every setting and each widget's place. The legacy ids also still ship
// (thin copies of the one package), so nothing fails before this has run.
//
// Generated by make_deb from templates/one-theme-update.js; the id tables and the
// per-widget setting keys are holes filled from the emitters.

var wallpaperIds = $wallpaperIds;   // { "org.el.openglo.live.elazure": "org.el.openglo.live", ... }
var appletIds = $appletIds;         // { "org.el.segclock.elazure": "org.el.segclock", ... }
var appletKeys = $appletKeys;       // { "org.el.segclock": ["use24h", ...], "org.el.notifymarquee": [...] }

// the wallpaper: a missing PLUGIN fails the whole containment, so this comes first
var ds = desktops();
for (var i = 0; i < ds.length; i++) {
    var d = ds[i];
    var to = wallpaperIds[d.wallpaperPlugin];
    if (to) d.wallpaperPlugin = to;
}

// the applets: add the one widget where the legacy one sits, copy its settings, remove the legacy one
var cs = desktops().concat(panels());
for (var c = 0; c < cs.length; c++) {
    var cont = cs[c];
    var ids = cont.widgetIds;
    for (var j = 0; j < ids.length; j++) {
        var old = cont.widgetById(ids[j]);
        var target = appletIds[old.type];
        if (!target) continue;
        var g = old.geometry;
        var fresh = cont.addWidget(target, g.x, g.y, g.width, g.height);
        var keys = appletKeys[target] || [];
        old.currentConfigGroup = ["General"];
        fresh.currentConfigGroup = ["General"];
        for (var k = 0; k < keys.length; k++) {
            var v = old.readConfig(keys[k]);
            if (v !== undefined && v !== null && v !== "") fresh.writeConfig(keys[k], v);
        }
        fresh.reloadConfig();
        old.remove();
    }
}
